import CommentFeed from "./CommentFeed";

const SLUG = "a1";

function App() {
  return (
    <main className="page">
      <h1>Feed</h1>
      <CommentFeed slug={SLUG} />
    </main>
  );
}

export default App;

function CommentRow({ body, author, createdAt }) {
  const username = author?.username ?? "unknown";
  const date = createdAt ? new Date(createdAt).toLocaleDateString() : "";

  return (
    <div className="comment">
      <p className="comment-body">{body}</p>
      <p className="comment-meta">
        {username} · {date}
      </p>
    </div>
  );
}

export default CommentRow;

import { useEffect, useState } from "react";
import { getComments } from "./api";
import CommentRow from "./CommentRow";

function CommentFeed({ slug }) {
  const [comments, setComments] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    getComments(slug)
      .then(setComments)
      .catch((err) => setError(err.message));
  }, [slug]);

  if (error) return <p className="error">{error}</p>;
  if (comments.length === 0) return null;

  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentFeed;

"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

class User extends Model {
  static associate() {
    this.hasMany(Article, { foreignKey: "userId", onDelete: "CASCADE" });
    this.hasMany(Comment, { foreignKey: "userId" });
  }

  toJSON() {
    const data = { ...this.get() };
    delete data.id;
    delete data.updatedAt;
    delete data.createdAt;
    return data;
  }
}

class Article extends Model {
  static associate() {
    this.belongsTo(User, { foreignKey: "userId", as: "author" });
    this.hasMany(Comment, { foreignKey: "articleId", onDelete: "cascade" });
  }

  toJSON() {
    const data = { ...this.get() };
    delete data.id;
    delete data.userId;
    return data;
  }
}

class Comment extends Model {
  static associate() {
    this.belongsTo(Article, { foreignKey: "articleId" });
    this.belongsTo(User, { as: "author", foreignKey: "userId" });
  }

  toJSON() {
    const data = { ...this.get() };
    delete data.articleId;
    delete data.userId;
    return data;
  }
}

User.init(
  { username: DataTypes.STRING },
  { sequelize, modelName: "User" },
);

Article.init(
  { slug: DataTypes.STRING },
  { sequelize, modelName: "Article" },
);

Comment.init(
  {
    id: {
      allowNull: false,
      autoIncrement: true,
      primaryKey: true,
      type: DataTypes.INTEGER,
    },
    body: DataTypes.TEXT,
  },
  { sequelize, modelName: "Comment" },
);

User.associate();
Article.associate();
Comment.associate();

module.exports = { sequelize, User, Article, Comment };

export async function getComments(slug) {
  const res = await fetch(`/api/articles/${slug}/comments`);
  if (!res.ok) {
    throw new Error(`Failed to load comments: ${res.status}`);
  }
  const data = await res.json();
  return data.comments;
}

const express = require("express");
const cors = require("cors");
const { sequelize, User, Article, Comment } = require("./models");

const PORT = 3001;
const app = express();

app.use(cors());

async function seed() {
  const [user] = await User.findOrCreate({
    where: { username: "u1" },
    defaults: { username: "u1" },
  });

  const [article] = await Article.findOrCreate({
    where: { slug: "a1" },
    defaults: { slug: "a1", userId: user.id },
  });

  const count = await Comment.count({ where: { articleId: article.id } });
  if (count === 0) {
    await Comment.bulkCreate([
      { body: "c1", articleId: article.id, userId: user.id },
      { body: "c2", articleId: article.id, userId: user.id },
    ]);
  }
}

app.get("/api/articles/:slug/comments", async (req, res) => {
  try {
    const { slug } = req.params;
    const article = await Article.findOne({ where: { slug } });
    if (!article) {
      return res.status(404).json({ error: "not_found" });
    }

    const comments = await article.getComments({
      include: [{ model: User, as: "author", attributes: ["username"] }],
    });

    res.json({ comments });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: "server_error" });
  }
});

(async () => {
  try {
    await sequelize.sync({ alter: true });
    await seed();
    app.listen(PORT, () =>
      console.log(`Server running on http://localhost:${PORT}`),
    );
  } catch (error) {
    console.error("Unable to start:", error);
    process.exit(1);
  }
})();

